style.css:
@-moz-document domain("roblox.com"), domain("www.roblox.com") {
body {
        background: url("https://i.imgur.com/MdyD5On.jpeg") no-repeat center center fixed !important;
        background-size: cover !important;
    }

    /* Make main containers semi-transparent */
    .container-main,
    .content,
    .game-home-page,
    .games-page,
    .profile-container,
    .navbar,
    .home-container,
    .content,
    .container-footer {
        background-color: rgba(255, 255, 255, 0.7) !important;
    }

    /* Remove backgrounds from outer sections */
    .rbx-body,
    .main-content,
    #navigation,
    .app,
    #root {
        background: transparent !important;
    }

    /* Optional: Darken scrollbars to match */
    ::-webkit-scrollbar {
        background: rgba(0, 0, 0, 0.2);
    }
    ::-webkit-scrollbar-thumb {
        background: rgba(0, 0, 0, 0.5);
    }
}
